-- ---------------------------------------------------------------------------
-- Gaia PostgreSQL development target: schema.
--
-- A synthetic retail database used as Gaia's second development target
-- (decision D25). It is NOT Gaia's metadata store and must never live in the
-- same database as it. All data is generated by infra/pg-target/seed.py;
-- every name, e-mail, phone, national ID and IBAN is synthetic.
--
-- Built deliberately for the Phase 3 worst-case premise (D23):
--   * almost no comments (exactly three, to exercise comment reading)
--   * a `legacy` schema with meaningless names and no declared keys between
--     tables, dates as yyyymmdd integers, flags as 'Y'/'N', numbers as text
--   * undeclared references (employee ids, store codes, customer codes)
--   * one NOT VALID foreign key, one NOT VALID check, and a table
--     (finance.invoices) whose FK enforcement triggers are disabled — the
--     PostgreSQL equivalent of a disabled FK — with orphans inserted after
--   * enum and domain types, identity, serial and generated columns
--   * a partitioned table, expression and partial indexes
--   * views with pass-through and computed columns, an alias-only view over
--     the legacy table, and a materialized view
--   * arithmetic identities (subtotal + tax + shipping = total, f5 * f6 = f7)
--
-- Applied by seed.py (`make pg-target-seed`), which drops and recreates the
-- schemas below. Requires PostgreSQL 13+; developed against 16 and 18.
-- ---------------------------------------------------------------------------

SET client_min_messages = warning;

DROP SCHEMA IF EXISTS rpt, legacy, finance, sales, store, product, hr, crm CASCADE;

CREATE SCHEMA crm;
CREATE SCHEMA hr;
CREATE SCHEMA product;
CREATE SCHEMA store;
CREATE SCHEMA sales;
CREATE SCHEMA finance;
CREATE SCHEMA legacy;
CREATE SCHEMA rpt;

-- -- types -------------------------------------------------------------------

CREATE DOMAIN crm.email_address AS varchar(320)
    CHECK (VALUE ~ '^[^@\s]+@[^@\s]+\.[a-z]{2,}$');

CREATE TYPE crm.customer_segment AS ENUM ('retail', 'smb', 'corporate', 'vip');
CREATE TYPE sales.sales_channel  AS ENUM ('store', 'web', 'mobile', 'phone');
CREATE TYPE sales.order_status   AS ENUM ('new', 'paid', 'shipped', 'delivered', 'cancelled', 'returned');

-- -- hr ----------------------------------------------------------------------

CREATE TABLE hr.departments (
    dept_id      smallint PRIMARY KEY,
    dept_code    char(3)      NOT NULL UNIQUE,
    name         varchar(80)  NOT NULL,
    cost_center  varchar(8)   NOT NULL
);

CREATE TABLE hr.employees (
    employee_id      serial PRIMARY KEY,                 -- serial: owned sequence
    emp_no           varchar(8)    NOT NULL UNIQUE,
    first_name       varchar(60)   NOT NULL,
    last_name        varchar(60)   NOT NULL,
    email            varchar(200),                       -- plain text, some malformed
    hire_date        date          NOT NULL,
    termination_date date,
    dept_id          smallint      NOT NULL REFERENCES hr.departments (dept_id),
    manager_id       integer       REFERENCES hr.employees (employee_id),
    job_title        varchar(80)   NOT NULL,
    salary           numeric(10,2) NOT NULL,
    salary_currency  char(3)       NOT NULL DEFAULT 'TRY',
    is_manager       boolean       NOT NULL DEFAULT false,
    CONSTRAINT ck_employees_dates CHECK (termination_date IS NULL OR termination_date >= hire_date)
);

-- -- store -------------------------------------------------------------------

CREATE TABLE store.stores (
    store_id    smallint PRIMARY KEY,
    store_code  char(4)      NOT NULL UNIQUE,
    name        varchar(120) NOT NULL,
    city        varchar(60)  NOT NULL,
    district    varchar(60),
    opened_on   date         NOT NULL,
    manager_id  integer,                                  -- undeclared -> hr.employees
    sqm         numeric(8,1)
);

-- -- crm ---------------------------------------------------------------------

CREATE TABLE crm.customers (
    customer_id        bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_code      varchar(12)   NOT NULL UNIQUE,
    first_name         varchar(60)   NOT NULL,
    last_name          varchar(60)   NOT NULL,
    email              crm.email_address,
    phone              varchar(20),
    national_id        char(11),
    birth_date         date,
    gender             char(1)       NOT NULL DEFAULT 'U' CHECK (gender IN ('F', 'M', 'U')),
    segment            crm.customer_segment NOT NULL DEFAULT 'retail',
    is_active          boolean       NOT NULL DEFAULT true,
    loyalty_points     integer       NOT NULL DEFAULT 0 CHECK (loyalty_points >= 0),
    iban               varchar(34),
    referred_by        bigint        REFERENCES crm.customers (customer_id),
    preferred_store_id smallint      REFERENCES store.stores (store_id),
    created_at         timestamptz   NOT NULL DEFAULT now(),
    updated_at         timestamptz
);

CREATE TABLE crm.addresses (
    address_id    bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id   bigint       NOT NULL REFERENCES crm.customers (customer_id) ON DELETE CASCADE,
    address_type  char(1)      NOT NULL CHECK (address_type IN ('B', 'S')),
    line1         varchar(200) NOT NULL,
    district      varchar(60),
    city          varchar(60)  NOT NULL,
    postal_code   char(5),
    country_code  char(2)      NOT NULL DEFAULT 'TR',
    is_default    boolean      NOT NULL DEFAULT false,
    address_hash  char(64)     NOT NULL                  -- sha256 of the normalized address
);

CREATE TABLE crm.customer_notes (
    note_id     bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id bigint      NOT NULL REFERENCES crm.customers (customer_id),
    note        text        NOT NULL,
    created_by  integer     NOT NULL,                     -- undeclared -> hr.employees
    created_at  timestamptz NOT NULL
);

-- -- product -----------------------------------------------------------------

CREATE TABLE product.categories (
    category_id smallint PRIMARY KEY,
    parent_id   smallint REFERENCES product.categories (category_id),
    name        varchar(80) NOT NULL
);

CREATE TABLE product.suppliers (
    supplier_id        integer PRIMARY KEY,
    name               varchar(120) NOT NULL,
    tax_no             char(10)     NOT NULL UNIQUE,
    country_code       char(2)      NOT NULL,
    iban               varchar(34),
    payment_terms_days smallint     NOT NULL DEFAULT 30
);

CREATE TABLE product.products (
    product_id      integer PRIMARY KEY,
    sku             varchar(16)   NOT NULL UNIQUE,
    name            varchar(160)  NOT NULL,
    category_id     smallint      NOT NULL REFERENCES product.categories (category_id),
    supplier_id     integer       NOT NULL REFERENCES product.suppliers (supplier_id),
    unit_cost       numeric(12,2) NOT NULL,
    list_price      numeric(12,2) NOT NULL CHECK (list_price >= 0),
    vat_rate        numeric(4,2)  NOT NULL CHECK (vat_rate IN (0, 1, 10, 20)),
    weight_g        integer,
    is_discontinued boolean       NOT NULL DEFAULT false,
    attributes      jsonb,
    launched_on     date
);

CREATE TABLE product.price_history (
    product_id integer       NOT NULL REFERENCES product.products (product_id),
    valid_from date          NOT NULL,
    valid_to   date,
    price      numeric(12,2) NOT NULL,
    PRIMARY KEY (product_id, valid_from)
);

CREATE TABLE store.inventory (
    store_id        smallint    NOT NULL REFERENCES store.stores (store_id),
    product_id      integer     NOT NULL REFERENCES product.products (product_id),
    qty_on_hand     integer     NOT NULL,
    reorder_level   integer     NOT NULL,
    last_counted_at timestamptz,
    PRIMARY KEY (store_id, product_id)
);

-- -- sales -------------------------------------------------------------------

CREATE TABLE sales.orders (
    order_id       bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    order_no       varchar(20)   NOT NULL UNIQUE,
    customer_id    bigint        NOT NULL REFERENCES crm.customers (customer_id),
    store_id       smallint      REFERENCES store.stores (store_id),
    channel        sales.sales_channel NOT NULL,
    status         sales.order_status  NOT NULL,
    order_date     date          NOT NULL,
    ordered_at     timestamptz   NOT NULL,
    shipped_at     timestamptz,
    delivered_at   timestamptz,
    currency_code  char(3)       NOT NULL DEFAULT 'TRY',
    subtotal       numeric(14,2) NOT NULL,
    tax_total      numeric(14,2) NOT NULL,
    shipping_fee   numeric(10,2) NOT NULL DEFAULT 0,
    total_amount   numeric(14,2) NOT NULL,
    payment_method varchar(12),
    coupon_code    varchar(16),
    sales_rep_id   integer,                               -- undeclared -> hr.employees
    source_system  varchar(10)   NOT NULL
);

CREATE TABLE sales.order_lines (
    order_line_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    order_id      bigint        NOT NULL REFERENCES sales.orders (order_id),
    line_no       smallint      NOT NULL,
    product_id    integer       NOT NULL REFERENCES product.products (product_id),
    quantity      integer       NOT NULL CHECK (quantity > 0),
    unit_price    numeric(12,2) NOT NULL,
    discount_pct  numeric(5,2)  NOT NULL DEFAULT 0 CHECK (discount_pct BETWEEN 0 AND 100),
    line_subtotal numeric(14,2) GENERATED ALWAYS AS
                  (round(quantity * unit_price * (1 - discount_pct / 100), 2)) STORED,
    line_tax      numeric(14,2) NOT NULL,
    condition     char(1)       NOT NULL DEFAULT 'N',
    CONSTRAINT uq_order_lines_order_line UNIQUE (order_id, line_no)
);

CREATE TABLE sales.payments (
    payment_id  bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    order_id    bigint        NOT NULL REFERENCES sales.orders (order_id),
    paid_at     timestamptz   NOT NULL,
    amount      numeric(14,2) NOT NULL,
    method      varchar(12)   NOT NULL,
    card_bin    char(6),
    card_last4  char(4),
    auth_code   varchar(12),
    status      char(1)       NOT NULL
);

CREATE TABLE sales.returns (
    return_id     bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    order_line_id bigint        NOT NULL,
    returned_at   timestamptz   NOT NULL,
    qty           integer       NOT NULL,
    reason_code   varchar(4)    NOT NULL,
    refund_amount numeric(14,2) NOT NULL
);
-- The FK is added NOT VALID after loading (see seed.py): "not trusted".

CREATE TABLE sales.order_events (
    event_id   bigint      NOT NULL,
    order_id   bigint      NOT NULL,                      -- no FK: event log
    event_type smallint    NOT NULL,
    event_at   timestamptz NOT NULL,
    actor      varchar(20) NOT NULL,
    payload    jsonb,
    PRIMARY KEY (event_id, event_at)
) PARTITION BY RANGE (event_at);

CREATE TABLE sales.order_events_2023 PARTITION OF sales.order_events
    FOR VALUES FROM ('2023-01-01') TO ('2024-01-01');
CREATE TABLE sales.order_events_2024 PARTITION OF sales.order_events
    FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');
CREATE TABLE sales.order_events_2025 PARTITION OF sales.order_events
    FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');
CREATE TABLE sales.order_events_default PARTITION OF sales.order_events DEFAULT;

-- -- finance -----------------------------------------------------------------

CREATE TABLE finance.currencies (
    currency_code char(3)     PRIMARY KEY,
    name          varchar(60) NOT NULL,
    minor_unit    smallint    NOT NULL
);

CREATE TABLE finance.fx_rates (
    rate_date date          NOT NULL,
    from_ccy  char(3)       NOT NULL REFERENCES finance.currencies (currency_code),
    to_ccy    char(3)       NOT NULL REFERENCES finance.currencies (currency_code),
    rate      numeric(18,8) NOT NULL,
    PRIMARY KEY (rate_date, from_ccy, to_ccy)
);

CREATE TABLE finance.invoices (
    invoice_id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    invoice_no    varchar(20)   NOT NULL UNIQUE,
    order_id      bigint        NOT NULL REFERENCES sales.orders (order_id),
    issued_on     date          NOT NULL,
    due_on        date          NOT NULL,
    amount        numeric(14,2) NOT NULL,
    tax_amount    numeric(14,2) NOT NULL,
    currency_code char(3)       NOT NULL REFERENCES finance.currencies (currency_code),
    status        smallint      NOT NULL,                  -- 0 open, 1 paid, 2 overdue, 9 void
    CONSTRAINT ck_invoices_due CHECK (due_on >= issued_on)
);

CREATE TABLE finance.gl_entries (
    entry_id       bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    posted_on      date          NOT NULL,
    account_no     varchar(10)   NOT NULL,
    debit          numeric(14,2) NOT NULL DEFAULT 0,
    credit         numeric(14,2) NOT NULL DEFAULT 0,
    doc_type       char(2)       NOT NULL,
    doc_ref        varchar(20),
    fiscal_period  integer       NOT NULL,                 -- yyyymm
    CONSTRAINT ck_gl_one_side CHECK (debit = 0 OR credit = 0)
);

-- -- legacy: the worst case ---------------------------------------------------

CREATE TABLE legacy.tb_mst01 (
    c01 varchar(12) NOT NULL,   -- customer code (undeclared -> crm.customers.customer_code)
    c02 varchar(130),           -- full name
    c03 char(1),                -- 'Y'/'N' active
    c04 varchar(60),            -- city
    c05 integer,                -- registration date yyyymmdd
    c06 varchar(20),            -- phone digits
    c07 varchar(20)             -- credit limit, numeric stored as text
);

CREATE TABLE legacy.tb_trx02 (
    f1  bigint NOT NULL,        -- transaction id
    f2  varchar(12),            -- customer code
    f3  integer,                -- date yyyymmdd
    f4  integer,                -- time hhmmss
    f5  integer,                -- quantity
    f6  numeric(12,2),          -- unit price
    f7  numeric(14,2),          -- amount = f5 * f6
    f8  char(2),                -- status 'OK' / 'CN' / 'RT'
    f9  char(4),                -- store code (undeclared -> store.stores.store_code)
    f10 char(3)                 -- currency
);

CREATE TABLE legacy.tb_prm03 (
    grp char(3)     NOT NULL,
    k   varchar(10) NOT NULL,
    v   varchar(50)
);

CREATE TABLE legacy.xx_aux (
    id integer NOT NULL,
    a1 varchar(20),             -- always NULL
    a2 char(1),                 -- always 'X'
    a3 integer                  -- always 0
);

-- -- indexes -----------------------------------------------------------------

CREATE INDEX ix_customers_lower_email ON crm.customers (lower(email));
CREATE INDEX ix_customers_active_segment ON crm.customers (segment) WHERE is_active;
CREATE INDEX ix_orders_customer_date ON sales.orders (customer_id, order_date DESC) INCLUDE (total_amount);
CREATE INDEX ix_orders_status ON sales.orders (status);
CREATE INDEX ix_order_lines_product ON sales.order_lines (product_id);
CREATE INDEX ix_order_events_order ON sales.order_events (order_id);
CREATE INDEX ix_gl_entries_period_account ON finance.gl_entries (fiscal_period, account_no);
CREATE INDEX ix_products_attributes ON product.products USING gin (attributes);
CREATE INDEX ix_trx02_f2 ON legacy.tb_trx02 (f2);
CREATE UNIQUE INDEX ux_trx02_f1 ON legacy.tb_trx02 (f1);

-- -- views -------------------------------------------------------------------

CREATE VIEW rpt.v_customer_overview AS
SELECT c.customer_id,
       c.customer_code,
       c.first_name || ' ' || c.last_name              AS full_name,
       c.segment,
       s.city                                          AS preferred_store_city,
       date_part('year', age(DATE '2026-01-01', c.birth_date))::int AS age_years,
       count(o.order_id)                               AS order_count,
       coalesce(sum(o.total_amount), 0)                AS lifetime_value,
       max(o.ordered_at)                               AS last_order_at
FROM crm.customers c
LEFT JOIN store.stores s ON s.store_id = c.preferred_store_id
LEFT JOIN sales.orders o ON o.customer_id = c.customer_id AND o.status NOT IN ('cancelled')
GROUP BY c.customer_id, c.customer_code, c.first_name, c.last_name, c.segment, s.city, c.birth_date;

CREATE VIEW rpt.v_daily_sales AS
SELECT o.order_date,
       o.store_id,
       o.channel,
       count(*)                                        AS orders,
       sum(o.total_amount)                             AS revenue,
       avg(o.total_amount)                             AS avg_basket,
       sum(CASE WHEN o.status = 'returned' THEN 1 ELSE 0 END) AS returned_orders
FROM sales.orders o
WHERE o.status <> 'cancelled'
GROUP BY o.order_date, o.store_id, o.channel;

-- Pure aliasing over the legacy table: the only place its business names exist.
CREATE VIEW rpt.v_legacy_transactions AS
SELECT t.f1                                  AS transaction_id,
       t.f2                                  AS customer_code,
       to_date(t.f3::text, 'YYYYMMDD')       AS transaction_date,
       t.f5                                  AS quantity,
       t.f6                                  AS unit_price,
       t.f7                                  AS amount,
       t.f8                                  AS status_code,
       t.f9                                  AS store_code
FROM legacy.tb_trx02 t;

CREATE MATERIALIZED VIEW rpt.mv_product_margin AS
SELECT p.product_id,
       p.sku,
       p.list_price - p.unit_cost                                   AS margin,
       round((p.list_price - p.unit_cost) / nullif(p.list_price, 0) * 100, 2) AS margin_pct
FROM product.products p
WITH NO DATA;

-- -- the only three comments ---------------------------------------------------

COMMENT ON TABLE sales.orders IS 'Customer orders across all sales channels';
COMMENT ON COLUMN sales.orders.source_system IS 'Originating system of the order';
COMMENT ON COLUMN finance.gl_entries.fiscal_period IS 'Fiscal period as yyyymm';
